import compositionWeights from "@/data/demographics/composition-weights.json";
import type { CompositionWeights } from "./compositionWeightsSchema";

/**
 * Archetype to Layer-1 bucket weights, lifted out of the country seeds so a
 * client bundle can project archetype-keyed effects without pulling in the
 * seeds' census marginals. Generated by `npm run generate:composition`;
 * `compositionWeights.test.ts` fails if the data file drifts from the seeds.
 */
export const COMPOSITION_WEIGHTS = compositionWeights as CompositionWeights;
